import SwiftUI
import UIKit

enum BundledIcons {
    static let lienquanBase64 = ""
    static let freefreefireBase64 = ""
    static let freefiremaxBase64 = ""
    static let pubgBase64 = ""
    static let capcutBase64 = ""
    static let dazzcamBase64 = ""

    static func image(for bundleID: String) -> UIImage? {
        let map: [String: String] = [
            "com.garena.game.kgvn": lienquanBase64,
            "com.dts.freefireth": freefireBase64,
            "com.dts.freefiremax": freefireMaxBase64,
            "vn.vng.pubgmobile": pubgBase64,
            "com.lemon.lvoverseas": capcutBase64,
            "dazz.camera.vintagecamera": dazzcamBase64,
        ]
        guard let b64 = map[bundleID],
              let data = Data(base64Encoded: b64) else { return nil }
        return UIImage(data: data)
    }
}
